def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n == 99:
        return 'D'

    opp_def = 0
    my_def = 0
    for a, b in history:
        if a == 'D':
            my_def += 1
        if b == 'D':
            opp_def += 1

    start = n - 10
    if start < 0:
        start = 0

    recent_opp_def = 0
    recent_my_def = 0
    for i in range(start, n):
        a, b = history[i]
        if a == 'D':
            recent_my_def += 1
        if b == 'D':
            recent_opp_def += 1

    if opp_def * 2 > n or recent_opp_def >= 5:
        return 'D'

    if my_last == 'D' and opp_last == 'D':
        if recent_opp_def <= 4 and opp_def <= max(3, n // 3):
            return 'C'
        return 'D'

    if opp_last == 'D' and my_last == 'C':
        caused = False
        if n >= 2 and history[-2][0] == 'D':
            caused = True

        if caused and recent_opp_def <= 4 and opp_def <= max(4, n // 3):
            return 'C'

        if recent_my_def >= 3 and recent_opp_def <= 4 and opp_def <= max(3, n // 4):
            return 'C'

        return 'D'

    if my_last == 'D' and opp_last == 'C':
        if opp_def == 0:
            return 'D'
        return 'C'

    if opp_def == 0:
        if n >= 5:
            return 'D'

    return 'C'
